using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;using TORSEPAN.Domain.Entities;
namespace TORSEPAN.Infrastructure.Persistence.Configurations;
public sealed class AccountingPartyConfiguration:IEntityTypeConfiguration<AccountingParty>{public void Configure(EntityTypeBuilder<AccountingParty>b){b.ToTable("AccountingParties");b.HasKey(x=>x.Id);b.Property(x=>x.Id).ValueGeneratedNever();b.Property(x=>x.Name).HasMaxLength(200).IsRequired();b.Property(x=>x.Company).HasMaxLength(200);b.Property(x=>x.Phone).HasMaxLength(50);b.Property(x=>x.Notes).HasMaxLength(1000);b.HasIndex(x=>x.Name);}}
public sealed class AccountingDocumentConfiguration:IEntityTypeConfiguration<AccountingDocument>{public void Configure(EntityTypeBuilder<AccountingDocument>b){b.ToTable("AccountingDocuments");b.HasKey(x=>x.Id);b.Property(x=>x.Id).ValueGeneratedNever();b.Property(x=>x.Title).HasMaxLength(250).IsRequired();b.Property(x=>x.TotalAmount).HasPrecision(18,2);b.Property(x=>x.PaidAmount).HasPrecision(18,2);b.Property(x=>x.Notes).HasMaxLength(1500);b.HasOne(x=>x.Party).WithMany().HasForeignKey(x=>x.PartyId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.Handpan).WithMany().HasForeignKey(x=>x.HandpanId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.PayrollPayment).WithMany().HasForeignKey(x=>x.PayrollPaymentId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.CreatedByUser).WithMany().HasForeignKey(x=>x.CreatedByUserId).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>x.PayrollPaymentId).IsUnique();b.HasIndex(x=>new{x.Type,x.CreatedAt});b.HasIndex(x=>x.DueDate);}}
